BEGIN;
SET LOCAL lock_timeout='5s';
CREATE TEMP TABLE specialist_songs (lane text,k text,title text,artist text,year int,v int[],sub_lane text,canon int,routing int) ON COMMIT DROP;
CREATE TEMP TABLE specialist_pairs(lane text,a text,b text,tests text[],phrase text,why text,w int) ON COMMIT DROP;
DO $guard$ BEGIN
IF EXISTS(SELECT 1 FROM specialist_songs n JOIN public.songs s ON lower(btrim(s.title))=lower(btrim(n.title)) AND lower(btrim(s.artist))=lower(btrim(n.artist)) WHERE s.id<>md5('musicdna:'||n.lane||':2026-11-10:song:'||n.k)::uuid) THEN RAISE EXCEPTION 'Existing song identity collision: review before import'; END IF;
END $guard$;
WITH calc AS (SELECT n.*, (SELECT count(*)::int FROM unnest(v) x WHERE x<=30 OR x>=70) strong,(SELECT count(*)::int FROM unnest(v) x WHERE x<35 OR x>65) nn FROM specialist_songs n), metrics AS(SELECT c.*,least(25,6+strong+CASE WHEN canon<95 THEN 3 ELSE 0 END) pol,least(20,7+nn) richness,least(15,6+ceil(strong/2.0)::int) ident,CASE WHEN year<2000 THEN 10 WHEN year<=2016 THEN 8 WHEN year<=2021 THEN 5 ELSE 3 END longevity,CASE WHEN routing<80 THEN 13 ELSE 10 END crossmap FROM calc c)
SELECT md5('musicdna:'||lane||':2026-11-10:song:'||k)::uuid,title,artist,year,lane,lane,sub_lane,false,v[1],v[2],v[3],v[4],v[5],v[6],v[7],v[8],v[9],v[10],canon,routing,pol+richness+9+ident+longevity+crossmap,ARRAY(SELECT ax FROM unnest(ARRAY['movement','atmosphere','immersion','scale','community','perspective','confidence','tension','texture','transformation']) WITH ORDINALITY d(ax,i) ORDER BY abs(v[i]-50) DESC,i LIMIT 3),pol,richness,9,ident,longevity,crossmap,lane||'_editorial_v1',now(),jsonb_build_object('method','editorial_axis_estimates','listener_validated',false,'review_status','provisional','source','data/musicdna specialist expansion 2026-11-10','existing_catalog_rescored',false) FROM metrics ON CONFLICT(id) DO NOTHING;
SELECT md5('musicdna:'||lane||':2026-11-10:pair:'||least(a,b)||'|'||greatest(a,b))::uuid,md5('musicdna:'||lane||':2026-11-10:song:'||a)::uuid,md5('musicdna:'||lane||':2026-11-10:song:'||b)::uuid,tests,why,why||' Editorial contrast only; listener split not yet measured.',phrase,lane,false,w,'Unmeasured; listener validation pending',2,false FROM specialist_pairs ON CONFLICT(id) DO NOTHING;
DO $audit$ DECLARE sc int;pc int;detail text; BEGIN
SELECT count(*) INTO sc FROM specialist_songs n JOIN public.songs s ON s.id=md5('musicdna:'||n.lane||':2026-11-10:song:'||n.k)::uuid;
SELECT count(*) INTO pc FROM specialist_pairs n JOIN public.pairings p ON p.id=md5('musicdna:'||n.lane||':2026-11-10:pair:'||least(n.a,n.b)||'|'||greatest(n.a,n.b))::uuid;
IF sc<>69 OR pc<>46 THEN RAISE EXCEPTION 'Incomplete specialist import: % songs / % pairings',sc,pc; END IF;
SELECT string_agg(n.lane||':'||n.a||'/'||n.b||':'||t||'='||coalesce(to_jsonb(sa)->>t,'NULL')||'/'||coalesce(to_jsonb(sb)->>t,'NULL')||':lanes='||sa.lane||'/'||sb.lane||'/'||p.lane,', ') INTO detail FROM specialist_pairs n JOIN public.pairings p ON p.id=md5('musicdna:'||n.lane||':2026-11-10:pair:'||least(n.a,n.b)||'|'||greatest(n.a,n.b))::uuid JOIN public.songs sa ON sa.id=p.song_a_id JOIN public.songs sb ON sb.id=p.song_b_id CROSS JOIN LATERAL unnest(p.tests) t WHERE t NOT IN ('movement','atmosphere','immersion','scale','community','perspective','confidence','tension','texture','transformation') OR (to_jsonb(sa)->>t) IS NULL OR (to_jsonb(sb)->>t) IS NULL OR abs((to_jsonb(sa)->>t)::int-(to_jsonb(sb)->>t)::int)<20 OR sa.lane<>p.lane OR sb.lane<>p.lane;
IF detail IS NOT NULL THEN RAISE EXCEPTION 'Specialist test/lane audit failed: %',detail; END IF;
END $audit$;
UPDATE public.songs s SET active=true FROM specialist_songs n WHERE s.id=md5('musicdna:'||n.lane||':2026-11-10:song:'||n.k)::uuid AND NOT s.active;
UPDATE public.pairings p SET active=true FROM specialist_pairs n WHERE p.id=md5('musicdna:'||n.lane||':2026-11-10:pair:'||least(n.a,n.b)||'|'||greatest(n.a,n.b))::uuid AND NOT p.active;
COMMIT;