INSERT INTO specialist_pairs VALUES
('yacht_rock','peg','sailing',ARRAY['movement','immersion','community'],'Studio chrome, or open water with no shore in sight?','Peg rewards precise ensemble propulsion; Sailing drifts into patient, private atmosphere.',87),
('yacht_rock','rosanna','deacon_blues',ARRAY['movement','community','confidence'],'The studio band punches in, or the narrator disappears after hours?','Rosanna drives a large, assured chorus; Deacon Blues sits alone inside an elaborate, vulnerable account.',88),
('yacht_rock','what_a_fool','baby_come_back',ARRAY['movement','confidence','community'],'Dance around the heartbreak, or say you need them back?','The Doobie Brothers keep romantic denial buoyant; Player exposes a slower, less confident plea.',85),
('yacht_rock','i_keep_forgettin','reminiscing',ARRAY['movement','immersion','atmosphere'],'Bassline with a grudge, or harmonies that let yesterday breathe?','Michael McDonald''s groove insists on the present; Little River Band rewards a gentler, longer memory.',83),
('yacht_rock','lowdown','biggest_part',ARRAY['movement','perspective','confidence'],'Call somebody out, or tell somebody they''re the whole world?','Lowdown watches and judges with swagger; Biggest Part of Me offers open reassurance.',86),
('yacht_rock','georgy_porgy','this_is_it',ARRAY['immersion','confidence','atmosphere'],'Let the pocket hypnotize you, or make the big declaration?','Toto invites patient close listening; Kenny Loggins turns soft rock into a more commanding statement.',84),
('yacht_rock','you_make_my_dreams','sailing',ARRAY['movement','atmosphere','community'],'Kick the door open smiling, or vanish behind the horizon?','Hall & Oates make pleasure instant and public; Christopher Cross makes pleasure weightless and solitary.',89),
('yacht_rock','i_cant_go_for_that','summer_breeze',ARRAY['movement','confidence','community'],'Set a boundary in velvet, or let the whole day drift by?','Hall & Oates keep a polished beat and a firm stance; Seals & Crofts choose easy atmosphere.',83),
('yacht_rock','deacon_blues','reminiscing',ARRAY['community','confidence','perspective'],'The lonely genius at closing time, or the couple replaying their favorite night?','Deacon Blues observes alienation from within; Reminiscing keeps a warmer, more shared memory.',86),
('yacht_rock','peg','georgy_porgy',ARRAY['immersion','perspective','confidence'],'Perfectly cut edges, or a groove that refuses to hurry?','Peg presents crisp observation and control; Georgy Porgy settles into an intimate, more vulnerable pocket.',84),
('disco','good_times','i_feel_love',ARRAY['immersion','perspective','transformation'],'The band runs the room, or the machine dreams the future?','Chic offers immediate human lockstep; Donna Summer invites a long synthetic, more abstract surrender.',90),
('disco','i_feel_love','stayin_alive',ARRAY['immersion','perspective','transformation'],'Ride the impossible pulse, or strut in a perfect suit?','I Feel Love pushes disco toward machine immersion; Stayin'' Alive gives the listener a character and a clear pose.',90),
('disco','i_will_survive','dont_leave_me',ARRAY['confidence'],'Walk out standing tall, or ask them not to go?','Gloria Gaynor makes recovery an act of command; Thelma Houston leaves the emotional request exposed.',81),
('disco','september','supernature',ARRAY['immersion','community','tension'],'A room full of old friends, or a disco on another planet?','Earth, Wind & Fire keep celebration immediate and welcoming; Cerrone brings distance, suspense and synthetic danger.',92),
('disco','we_are_family','shame',ARRAY['confidence','tension'],'Belong to everybody, or dance with a private doubt?','Sister Sledge celebrate certainty and fellowship; Evelyn King lets embarrassment flicker through the groove.',84),
('disco','disco_inferno','rock_your_baby',ARRAY['scale','tension'],'Set the building on fire, or dim the lights for two?','The Trammps make disco huge and heated; George McCrae keeps it tender and almost weightless.',85),
('disco','get_down_tonight','love_hangover',ARRAY['immersion','atmosphere','transformation'],'Get to the hook, or wait for the lights to change?','KC gives an immediate dance-floor command; Diana Ross takes the scenic route from intimacy to release.',88),
('disco','im_coming_out','dont_leave_me',ARRAY['confidence','tension'],'Announce your arrival, or plead for one more chance?','Diana Ross projects independence; Thelma Houston transforms desire into an exposed appeal.',83),
('disco','you_make_me_feel','get_down_tonight',ARRAY['scale','atmosphere','transformation'],'A whole new self, or just one terrific night out?','Sylvester turns pleasure into an enormous evolving declaration; KC stays in the present groove.',87),
('disco','turn_beat_around','love_hangover',ARRAY['atmosphere','immersion','transformation'],'Hit the percussion now, or let desire become the beat?','Vicki Sue Robinson never lets rhythmic momentum wait; Love Hangover earns its explosion through a long transition.',88),
('disco','dont_stop_til','dancing_queen',ARRAY['transformation'],'Watch the arrangement keep inventing itself, or sing the moment forever?','Michael Jackson''s groove keeps unfolding; ABBA offers a more self-contained, memory-making anthem.',74),
('disco','stayin_alive','i_will_survive',ARRAY['scale','transformation'],'Keep your cool, or make the whole room witness your comeback?','Bee Gees favor taut self-possession; Gloria Gaynor makes private reversal a larger shared event.',82),
('punk','blitzkrieg','london_calling',ARRAY['atmosphere','immersion','perspective'],'Three chords and a grin, or the end of the world on the radio?','The Ramones invite an instant shout; The Clash put a larger, more observant warning inside the charge.',88),
('punk','blitzkrieg','anarchy',ARRAY['perspective'],'Start a chant, or start an argument nobody can stop?','Ramones favor uncomplicated shared ignition; Sex Pistols make provocation itself the central statement.',80),
('punk','anarchy','ever_fallen',ARRAY['perspective','confidence','tension'],'Riot outside the door, or heartbreak behind the grin?','The Pistols bark a public challenge; Buzzcocks keep the pace but expose personal doubt.',90),
('punk','holiday','teenage_kicks',ARRAY['perspective','confidence','tension'],'A poisoned postcard, or a crush that moves faster than thinking?','Dead Kennedys make satire dangerous; The Undertones turn speed into emotionally direct, lower-pressure pleasure.',89),
('punk','new_rose','typical_girls',ARRAY['movement','atmosphere','immersion'],'Hit the first chord and run, or pull the whole song apart?','The Damned sprint on impact; The Slits dismantle the assumptions and structure along the way.',86),
('punk','los_angeles','straight_edge',ARRAY['community','atmosphere','immersion'],'A messy city after midnight, or a life drawn in permanent marker?','X paint a tangled scene; Minor Threat reduce the question to disciplined immediate refusal.',83),
('punk','rise_above','basket_case',ARRAY['confidence','tension','texture'],'Stand your ground, or admit the ground is moving?','Black Flag weaponize public certainty; Green Day make anxious vulnerability catchy and smoother.',89),
('punk','banned_dc','twelve_xu',ARRAY['community','transformation'],'A band that changes gears mid-flight, or a blade that never bends?','Bad Brains'' dynamics keep mutating; Wire compress intensity into a briefer, harsher form.',84),
('punk','bondage','self_esteem',ARRAY['perspective','confidence','tension'],'Fight the script, or confess you''re trapped inside it?','X-Ray Spex challenge the culture outward; Offspring direct their energy into private romantic self-criticism.',88),
('punk','london_calling','ruby_soho',ARRAY['perspective','tension','transformation'],'The siren outside, or friends singing all the way home?','The Clash expand political stakes; Rancid make the street-level story more communal and warm.',85),
('punk','typical_girls','holiday',ARRAY['atmosphere','immersion','tension'],'Unpick the machine slowly, or rip the warning label off?','The Slits make critique playful and exploratory; Dead Kennedys bring sharper, more immediate danger.',82),
('punk','alternative_ulster','ever_fallen',ARRAY['perspective','confidence','tension'],'Demand a different future, or wonder why love keeps failing?','Stiff Little Fingers turn anger outward; Buzzcocks make the same speed carry vulnerable confusion.',88),
('reggae','three_little_birds','marcus_garvey',ARRAY['immersion','perspective','tension'],'Tell the room it''ll be alright, or tell it what must change?','Marley brings an immediate communal reassurance; Burning Spear unfolds a more demanding political meditation.',90),
('reggae','harder_come','pressure_drop',ARRAY['perspective','tension'],'Defy the world, or let the rhythm do the talking?','Jimmy Cliff makes resistance explicit; Toots keeps its social energy closer to buoyant musical release.',84),
('reggae','israelites','night_nurse',ARRAY['perspective','community','atmosphere'],'Hear the struggle outside, or the ache behind the bedroom door?','Desmond Dekker''s social observation carries public strain; Gregory Isaacs opens a private, tender space.',88),
('reggae','money_pocket','legalize_it',ARRAY['perspective','tension','confidence'],'Keep it between two hearts, or take the argument to the street?','Dennis Brown wraps vulnerability in a friendly groove; Peter Tosh states an unambiguous public demand.',86),
('reggae','guess_who','three_little_birds',ARRAY['immersion','perspective','tension'],'A shadow at the gate, or the promise that it''ll pass?','Black Uhuru invite suspicious, layered immersion; Bob Marley replies with bright collective comfort.',88),
('reggae','king_tubby','money_pocket',ARRAY['movement','immersion','community'],'Let the echo tell the story, or let a singer come close?','Augustus Pablo''s dub strips away foreground reassurance; Dennis Brown keeps the groove human and accessible.',89),
('reggae','fisherman','get_busy',ARRAY['movement','atmosphere','immersion'],'Stay inside the trance, or send the whole dance floor moving?','The Congos ask for slow spiritual attention; Sean Paul puts the moment and the crowd first.',89),
('reggae','bam_bam','legalize_it',ARRAY['perspective','tension','texture'],'Own the mic with a wink, or make it a megaphone?','Sister Nancy makes playful confidence contagious; Peter Tosh converts that command into sharper public argument.',86),
('reggae','zungu','handsworth',ARRAY['perspective','tension','texture'],'A dancehall dare, or a neighborhood drawing a line?','Yellowman rewards immediate deejay charisma; Steel Pulse push collective political accountability.',86),
('reggae','you_dont_love_me','welcome_jamrock',ARRAY['perspective','tension','confidence'],'One wounded heart, or a whole country on the witness stand?','Dawn Penn keeps intimacy exposed; Damian Marley places vivid public stakes over forceful rhythm.',90),
('reggae','get_busy','king_tubby',ARRAY['movement','community','immersion'],'Pack the floor now, or leave room for the echoes?','Sean Paul delivers full-body immediate company; Augustus Pablo lets space and time become the point.',88),
('reggae','pressure_drop','welcome_jamrock',ARRAY['perspective','tension'],'A groove that shakes off trouble, or one that refuses to look away?','Toots offers lighter communal buoyancy; Damian Marley puts a harder public diagnosis into the beat.',85);
